import React, { useState } from 'react';

var monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
var dayNames = ['Su','Mo','Tu','We','Th','Fr','Sa'];

function CalendarApp() {
  var now = new Date();
  var state = useState(new Date(now.getFullYear(), now.getMonth(), 1));
  var current = state[0];
  var setCurrent = state[1];
  var selState = useState(null);
  var selected = selState[0];
  var setSelected = selState[1];

  var year = current.getFullYear();
  var month = current.getMonth();
  var daysInMonth = new Date(year, month + 1, 0).getDate();
  var firstDay = new Date(year, month, 1).getDay();

  function prevMonth() { setCurrent(new Date(year, month - 1, 1)); }
  function nextMonth() { setCurrent(new Date(year, month + 1, 1)); }
  function goToday() { setCurrent(new Date(now.getFullYear(), now.getMonth(), 1)); setSelected(now.getDate()); }

  function isToday(d) { return d === now.getDate() && month === now.getMonth() && year === now.getFullYear(); }
  function isSelectedDay(d) { return d === selected; }

  function dayClass(d) {
    if (isSelectedDay(d)) return 'aspect-square flex items-center justify-center rounded-xl text-sm font-medium bg-blue-500 text-white scale-105';
    if (isToday(d)) return 'aspect-square flex items-center justify-center rounded-xl text-sm font-medium bg-blue-50 text-blue-600 border border-blue-200 dark:bg-blue-900 dark:text-blue-300 dark:border-blue-700';
    return 'aspect-square flex items-center justify-center rounded-xl text-sm font-medium text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800';
  }

  var blanks = [];
  for (var b = 0; b < firstDay; b++) blanks.push(b);
  var days = [];
  for (var d = 1; d <= daysInMonth; d++) days.push(d);

  return React.createElement('div', { className: 'bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 p-6 w-full max-w-md mx-auto font-sans' },
    React.createElement('div', { className: 'flex justify-between items-center mb-6' },
      React.createElement('div', null,
        React.createElement('h2', { className: 'text-2xl font-bold text-slate-800 dark:text-white' }, monthNames[month]),
        React.createElement('p', { className: 'text-sm text-slate-500 dark:text-slate-400' }, year)
      ),
      React.createElement('div', { className: 'flex gap-2' },
        React.createElement('button', { onClick: goToday, className: 'px-3 py-1 text-xs font-semibold text-blue-600 bg-blue-100 hover:bg-blue-200 dark:bg-blue-900 dark:text-blue-300 rounded-full' }, 'Today'),
        React.createElement('button', { onClick: prevMonth, className: 'p-2 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300' }, '<'),
        React.createElement('button', { onClick: nextMonth, className: 'p-2 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300' }, '>')
      )
    ),
    React.createElement('div', { className: 'grid grid-cols-7 gap-1 mb-2' },
      dayNames.map(function(n) { return React.createElement('div', { key: n, className: 'text-center text-xs font-medium text-slate-400 py-2' }, n); })
    ),
    React.createElement('div', { className: 'grid grid-cols-7 gap-1' },
      blanks.map(function(b) { return React.createElement('div', { key: 'b' + b, className: 'aspect-square' }); }),
      days.map(function(d) {
        return React.createElement('button', {
          key: d,
          onClick: function() { setSelected(d); },
          className: dayClass(d)
        }, d);
      })
    )
  );
}

var calendarPlugin = {
  id: 'community:calendar-v2',
  name: 'Calendar',
  apiVersion: 1,
  description: 'A clean interactive calendar plugin.',
  commands: [
    {
      id: 'open-calendar',
      label: 'Calendar',
      hint: 'Open the calendar dialog',
      run: function(ctx) { if (ctx.sdk) ctx.sdk.dialog.openCustom('calendar-main'); }
    }
  ],
  topbar: [
    {
      id: 'topbar-cal',
      label: 'Calendar',
      icon: React.createElement('svg', { width: 16, height: 16, fill: 'none', stroke: 'currentColor', viewBox: '0 0 24 24' },
        React.createElement('path', { strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 2, d: 'M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z' })
      ),
      onClick: function(ctx) { if (ctx && ctx.sdk) ctx.sdk.dialog.openCustom('calendar-main'); }
    }
  ],
  dialogs: [
    {
      id: 'calendar-main',
      render: function(props) {
        if (!props.open) return null;
        return React.createElement('div', {
          className: 'fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4',
          onClick: props.onClose
        },
          React.createElement('div', {
            className: 'relative',
            onClick: function(e) { e.stopPropagation(); }
          },
            React.createElement('button', {
              onClick: props.onClose,
              className: 'absolute -top-3 -right-3 w-7 h-7 flex items-center justify-center rounded-full bg-slate-700 text-white text-sm hover:bg-slate-600 z-10'
            }, 'x'),
            React.createElement(CalendarApp, null)
          )
        );
      }
    }
  ]
};

export default calendarPlugin;
